function isBillingDateTooOld(billingDate) {
  const billingDateObj = new Date(billingDate);
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - {{MAX_BILLING_DAYS_LOOKBACK}});
  return billingDateObj < cutoff;
}
